contract InvMutTest {
    C c;
    constructor() { c = new C(address(this), address(this), address(this)); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(address _nft) public {
        require(_nft != address(0));

        c.initialize(
            address(0),
            _nft,
            0,
            0,
            0,
            0,
            bytes32(0),
            false,
            false
        ); if (__ESBMC_reverted()) return;

        assert(c.nft() == _nft);
    }
}

