// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PrivatePool c;

    function setUp() public {
        c = new PrivatePool(address(this), address(this), address(this));
    }

    function _run(address _nft) internal {
        vm.assume(_nft != address(0));
        try c.initialize(
            address(0),
            _nft,
            0,
            0,
            0,
            0,
            bytes32(0),
            false,
            false
        ) {} catch { return; }
        assertTrue(c.nft() == _nft);
    }

    function testFuzz_run(address _nft) public {
        vm.assume(_nft.code.length == 0 && uint160(_nft) > 0xffff && _nft != address(this) && _nft != address(c) && _nft != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && _nft != 0x000000000000000000636F6e736F6c652e6c6f67 && _nft != 0x4e59b44847b379578588920cA78FbF26c0B4956C && _nft != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(_nft);
    }

    receive() external payable {}
}
